#!/bin/bash
set -e

B64_PARTS=()
B64_PARTS[0]=""
B64_PARTS[1]=""
B64_PARTS[2]=""
B64_PARTS[3]=""
B64_PARTS[4]=""
B64_PARTS[5]=""
B64_PARTS[6]=""
B64_PARTS[7]=""

# Reassemble and decode
FULL_B64=""
for i in $(seq 0 7); do
  FULL_B64="${FULL_B64}${B64_PARTS[$i]}"
done

python3 -c "
import base64, sys
b = sys.argv[1]
import os
os.makedirs("src/components/rms", exist_ok=True)
with open("src/components/rms/rent.tsx", "wb") as f:
    f.write(base64.b64decode(b))
print("OK: rent.tsx written (", len(base64.b64decode(b)), " bytes)")
" "$FULL_B64"